head.script:
scwin.createMouseEvent = function(ev, type) {
    if (ev.initMouseEvent) {
        if (WebSquare.util.isIE(9) || WebSquare.util.isIE(10)) {
            if (type.slice(0, 2) != "on") {
                type = "on" + type;
            }
            if (document.createEventObject) {
                var mouseEvent = document.createEventObject();
                mouseEvent.button = 0;
                ev.target.fireEvent(type, mouseEvent);
            }
        } else {
            var mouseEvent = document.createEvent("MouseEvent");
            if (type.slice(0, 2) == "on") {
                type = type.slice(2);
            }
            mouseEvent.initMouseEvent(type, true, true, window, 0,
                ev.screenX, ev.screenY, ev.clientX, ev.clientY,
                ev.ctrlKey, ev.altKey, ev.shiftKey, ev.metaKey,
                0, null);
            ev.target.dispatchEvent(mouseEvent);
        }
    } else {
        if (type.slice(0, 2) != "on") {
            type = "on" + type;
        }
        if (document.createEventObject) {
            var mouseEvent = document.createEventObject();
            mouseEvent.button = 0;
            WebSquare.wUnit.getDomById($p.id + ev).fireEvent(type, mouseEvent);
        }
    }
}
scwin.createDblClickEvent = function(ev) {
    scwin.createMouseEvent(ev, "onmousedown");
    scwin.createMouseEvent(ev, "onmouseup");
    scwin.createMouseEvent(ev, "onclick");
    scwin.createMouseEvent(ev, "onmousedown");
    scwin.createMouseEvent(ev, "onmouseup");
    scwin.createMouseEvent(ev, "onclick");
    scwin.createMouseEvent(ev, "ondblclick");
}
scwin.__triggerKeyboardEvent = function(el, keyCode) {
    var eventObj = document.createEventObject ?
        document.createEventObject() : document.createEvent("Events");
    if (eventObj.initEvent) {
        eventObj.initEvent("keydown", true, true);
    }
    eventObj.keyCode = keyCode;
    eventObj.which = keyCode;
    el.dispatchEvent ? el.dispatchEvent(eventObj) : el.fireEvent("onkeydown", eventObj);
}
scwin.setVal = function() {
    scwin.createDblClickEvent(evtObj['gridView1_cell_0_0']);
}
scwin.setVal1 = function() {
    scwin.__triggerKeyboardEvent(WebSquare.wUnit.getDomById('G_'+$p.id+'gridView1__col1'), 13);
}
scwin.checkVal = function() {
    return gridView1.getCellData(0, 0) == '25';
}
scwin.setVal2 = function() {
    scwin.createDblClickEvent(evtObj['gridView1_cell_0_1']);
}
scwin.setVal3 = function() {
    scwin.__triggerKeyboardEvent(WebSquare.wUnit.getDomById('G_'+$p.id+'gridView1__col2'), 13);
}
scwin.checkVal1 = function() {
    return gridView1.getCellData(0, 1) == '25';
}
scwin.unitTest = function() {
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_0_0').click();");
    WebSquare.wUnit.addCommand("set", "scwin.setVal()");
    WebSquare.wUnit.addCommand("pause", "50");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_'+$p.id+'gridView1__col1').setValue('25')");
    WebSquare.wUnit.addCommand("pause", "50");
    WebSquare.wUnit.addCommand("set", "scwin.setVal1()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_0_1').click();");
    WebSquare.wUnit.addCommand("set", "scwin.setVal2()");
    WebSquare.wUnit.addCommand("pause", "50");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_'+$p.id+'gridView1__col2').setValue('25')");
    WebSquare.wUnit.addCommand("pause", "50");
    WebSquare.wUnit.addCommand("set", "scwin.setVal3()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.evtObj = {};
    window.cell01 = WebSquare.wUnit.getDomById($p.id + "gridView1_cell_0_1");
    window.cell00 = WebSquare.wUnit.getDomById($p.id + "gridView1_cell_0_0");
    cell00.onclick = function(ev) {
        evtObj["gridView1_cell_0_0"] = ev;
    }
    cell01.onclick = function(ev) {
        evtObj["gridView1_cell_0_1"] = ev;
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
